   193	    private static async Task<(CommandResult Result, RecordedRequest Request)> RunWithApiResponseAsync(
   194	        string[] args,
   195	        string responseBody,
   196	        int statusCode = 200,
   197	        string reasonPhrase = "OK")
   198	    {
   199	        var port = GetFreePort();
   200	        using var listener = new HttpListener();
   201	        listener.Prefixes.Add($"http://127.0.0.1:{port}/");
   202	        listener.Start();
   203	
   204	        var request = Task.Run(async () =>
   205	        {
   206	            var context = await listener.GetContextAsync();
   207	            try
   208	            {
   209	                var recorded = await RecordedRequest.FromAsync(context.Request);
   210	                var bytes = Encoding.UTF8.GetBytes(responseBody);
   211	                context.Response.StatusCode = statusCode;
   212	                context.Response.StatusDescription = reasonPhrase;
   213	                context.Response.ContentType = "application/json";
   214	                context.Response.ContentLength64 = bytes.Length;
   215	                await context.Response.OutputStream.WriteAsync(bytes);
   216	                return recorded;
   217	            }
   218	            finally
   219	            {
   220	                context.Response.Close();
   221	            }
   222	        });
   223	
   224	        using var env = new EnvironmentScope($"http://127.0.0.1:{port}", "jt_test_key");
   225	        var result = await RunAsync(args);
   226	        var recordedRequest = await request.WaitAsync(TimeSpan.FromSeconds(5));
   227	        return (result, recordedRequest);
   228	    }
